import csv
with open('gtfs_extract/stop_times.txt', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    rows = list(reader)
print(f'Total stop_times: {len(rows)}')
print(f'Headers: {list(rows[0].keys())}')

# Check for times beyond 24:00:00
for r in rows[:5]:
    print(r)

# Check for times beyond 24:00:00
times_beyond = []
for r in rows:
    for col in ['arrival_time', 'departure_time']:
        t = r.get(col, '')
        if t and ':' in t:
            parts = t.split(':')
            hours = int(parts[0])
            if hours >= 24:
                times_beyond.append((r['trip_id'], r['stop_id'], col, t))
print(f'Times beyond 24h: {len(times_beyond)}')
if times_beyond:
    for t in times_beyond[:5]:
        print(t)
"
